function [px,py,pz]=CalPlaneLineIntersectPoint(en,planepoint,es,linepoint)
% en为法向量planepoint为平面上一个点的坐标es为直线的方向向量linepoint为直线上一个点的坐标
vpt=dot(en,es); %内积
