else
t=((planepoint(1)-linepoint(1))*en(1)+(planepoint(2)-linepoint(2))*en(2)+(planepoint(3)-linepoint(3))*en(3))
px=linepoint(1)+es(1)*t;
py=linepoint(2)+es(2)*t;
pz=linepoint(3)+es(3)*t;
end
end
